import type { HTMLAttributes } from "vue";

export interface LiquidGlassProps {
    /** 圆角大小（px） */
    radius?: number;
    /** 边框厚度比例（相对于最短边） */
    border?: number;
    /** 位移贴图的亮度（0-100） */
    lightness?: number;
    /** 高斯模糊偏移量（feGaussianBlur stdDeviation） */
    displace?: number;
    /** SVG 渐变混合模式 */
    blend?: string;
    /** 位移贴图 X 通道 */
    xChannel?: "R" | "G" | "B";
    /** 位移贴图 Y 通道 */
    yChannel?: "R" | "G" | "B";
    /** 位移贴图 alpha 透明度 */
    alpha?: number;
    /** 位移贴图模糊半径（px） */
    blur?: number;
    /** 红通道位移偏移量 */
    rOffset?: number;
    /** 绿通道位移偏移量 */
    gOffset?: number;
    /** 蓝通道位移偏移量 */
    bOffset?: number;
    /** 位移强度（负值向内折射） */
    scale?: number;
    /** 磨砂背景透明度 */
    frost?: number;
    /**
     * 容器定位方式
     * - `fixed`：全屏浮层（默认）
     * - `absolute`：相对父容器定位
     * - `relative`：普通文档流
     */
    position?: "fixed" | "absolute" | "relative" | "sticky";
    /** 内层插槽容器的额外 class */
    class?: HTMLAttributes["class"];
    /** 外层效果容器的额外 class */
    containerClass?: HTMLAttributes["class"];
}

export { default as LiquidGlass } from "./LiquidGlass.vue";

/** 液态玻璃效果容器的静态样式（动态属性 position / border-radius / --frost 由组件 baseStyle 覆盖注入） */
const effectStyles: Record<string, string> = {
  display: 'block',
  'border-radius': 'inherit',
  'backdrop-filter': 'url(#displacementFilter)',
  background: 'light-dark(hsl(0 0% 100% / var(--frost, 0)), hsl(0 0% 0% / var(--frost, 0)))',
  'box-shadow': [
    '0 0 2px 1px light-dark(color-mix(in oklch, canvasText, #0000 85%), color-mix(in oklch, canvasText, #0000 90%)) inset',
    '0 0 10px 4px light-dark(color-mix(in oklch, canvasText, #0000 90%), color-mix(in oklch, canvasText, #0000 95%)) inset',
    '0px 4px 16px rgba(17, 17, 26, 0.05)',
    '0px 8px 24px rgba(17, 17, 26, 0.05)',
    '0px 16px 56px rgba(17, 17, 26, 0.05)',
    '0px 4px 16px rgba(17, 17, 26, 0.05) inset',
    '0px 8px 24px rgba(17, 17, 26, 0.05) inset',
    '0px 16px 56px rgba(17, 17, 26, 0.05) inset',
  ].join(', '),
}

/** 内容区域插槽的静态样式 */
const slotContainerStyles: Record<string, string> = {
  width: '100%',
  height: '100%',
  overflow: 'hidden',
  'border-radius': 'inherit',
}

/** SVG 滤镜层的静态样式 */
const filterStyles: Record<string, string> = {
  position: 'absolute',
  inset: '0',
  width: '100%',
  height: '100%',
  'pointer-events': 'none',
}

export default {
  styles: {
    /** 外层效果容器（静态基础样式，动态注入属性由组件覆盖） */
    effect: effectStyles,
    /** 插槽内容区域 */
    slotContainer: slotContainerStyles,
    /** SVG 位移滤镜层 */
    filter: filterStyles,
  },
}
